         Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
         return new NewReservation(
-                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), guests, plan);
+                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), guests, 0, plan);
     }

     private static ErrorCode errorOf(Runnable action) {
@@ -159,4 +159,31 @@ class ReservationServiceTest {
     void anUnknownReservationIsNotFound() {
         assertEquals(ErrorCode.RESERVATION_NOT_FOUND, errorOf(() -> service.find(42)));
     }
+
+    @Test
+    void adultsAndChildrenCountTowardCapacity() {
+        // Room 101 has capacity 2: 1 adult + 2 children should fail
+        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
+        NewReservation tooMany = new NewReservation(
+                101, guest, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 1, 2, RatePlan.STANDARD);
+        assertEquals(ErrorCode.CAPACITY_EXCEEDED, errorOf(() -> service.create(tooMany)));
+    }
+
+    @Test
+    void childrenAreOptionalAndDefaultToZero() {
+        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD));
+        assertEquals(0, reservation.children());
+    }
+
+    @Test
+    void childrenCountIsStoredAndRetrieved() {
+        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
+        NewReservation withChildren = new NewReservation(
+                201, guest, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 1, 2, RatePlan.STANDARD);
+        Reservation created = service.create(withChildren);
+        assertEquals(2, created.children());
+
+        Reservation retrieved = service.find(created.id());
+        assertEquals(2, retrieved.children());
+    }
 }
